/**
 * Owns inert Time Wolf Consort lock, skip and reflection fact data for shared consumers.
 * Inputs are a machine event type and JSON.parse/no-reviver or proven inert
 * payload; outputs are the original detached fact shapes or null. Field, ID,
 * null and copy limits retain the existing reader policy. This browser reader
 * does not promise hostile Proxy zero-trap safety: Node ingress owns that check.
 * It never authorizes an action, reads a roster or resolves the mechanism effect.
 */
import { copyEventData } from "../inert-event-data";
export interface TimeConsortChoiceFact {
  actorId: number;
  day: number;
  targetId: number | null;
}
export interface TimeConsortSkipFact {
  actorId: number;
  day: number;
  reason: "exhausted" | "dead";
}
export interface TimeConsortReflectionFact {
  actorId: number;
  day: number;
  sourceId: number;
  requestedId: number;
  effectiveId: number;
  kind: "check" | "guard" | "poison";
}
function data(value: unknown): Record<string, unknown> | null {
  try {
    const v = copyEventData(value);
    return v && typeof v === "object" && !Array.isArray(v) ? (v as Record<string, unknown>) : null;
  } catch {
    return null;
  }
}
function id(v: unknown): v is number {
  return typeof v === "number" && Number.isSafeInteger(v) && v > 0 && v < Number.MAX_SAFE_INTEGER;
}
function keys(p: Record<string, unknown>, names: string[]): boolean {
  return Object.keys(p).length === names.length && names.every((k) => Object.hasOwn(p, k));
}
export function readTimeConsortChoiceFact(
  type: string,
  value: unknown,
): TimeConsortChoiceFact | null {
  if (type !== "time_consort_lock_committed") return null;
  const p = data(value);
  return p &&
    keys(p, ["actorId", "day", "targetId"]) &&
    id(p.actorId) &&
    id(p.day) &&
    (p.targetId === null || id(p.targetId))
    ? (p as unknown as TimeConsortChoiceFact)
    : null;
}
export function readTimeConsortSkipFact(type: string, value: unknown): TimeConsortSkipFact | null {
  if (type !== "time_consort_lock_skipped") return null;
  const p = data(value);
  return p &&
    keys(p, ["actorId", "day", "reason"]) &&
    id(p.actorId) &&
    id(p.day) &&
    (p.reason === "exhausted" || p.reason === "dead")
    ? (p as unknown as TimeConsortSkipFact)
    : null;
}
export function readTimeConsortReflectionFact(
  type: string,
  value: unknown,
): TimeConsortReflectionFact | null {
  if (type !== "time_consort_reflected") return null;
  const p = data(value);
  return p &&
    keys(p, ["actorId", "day", "sourceId", "requestedId", "effectiveId", "kind"]) &&
    [p.actorId, p.day, p.sourceId, p.requestedId, p.effectiveId].every(id) &&
    p.sourceId === p.effectiveId &&
    (p.kind === "check" || p.kind === "guard" || p.kind === "poison")
    ? (p as unknown as TimeConsortReflectionFact)
    : null;
}

/**
 * Owns Time Consort state construction, exact live reads and pure reflection selection.
 * Inputs are original role/history data and requested target facts; outputs preserve copied
 * player knowledge and existing target decisions. This boundary never commits a receipt.
 */
import type {
  ReflectionScope,
  TimeConsortChoice,
  TimeConsortState,
  TimeConsortReadState,
} from "@ai-werewolf-arena/game-contract";
import { types } from "node:util";
import { Camp, type RoleComponent } from "../../../../core";
export const TIME_CONSORT_ROLE = "time_wolf_consort" as const;
export const TIME_CONSORT_POLICY = "awa_time_consort_reflection_v1" as const;
function field(value: unknown, key: PropertyKey): unknown {
  if (!value || typeof value !== "object" || types.isProxy(value)) return undefined;
  const d = Object.getOwnPropertyDescriptor(value, key);
  return d && "value" in d ? d.value : undefined;
}
function exact(value: unknown, keys: readonly string[]): boolean {
  if (!value || typeof value !== "object" || types.isProxy(value) || Array.isArray(value))
    return false;
  const descriptors = Object.getOwnPropertyDescriptors(value);
  return (
    Reflect.ownKeys(descriptors).length === keys.length &&
    keys.every((k) => descriptors[k] && "value" in descriptors[k]!)
  );
}
function integer(value: unknown): value is number {
  return (
    typeof value === "number" &&
    Number.isSafeInteger(value) &&
    value > 0 &&
    value < Number.MAX_SAFE_INTEGER
  );
}
function arrayItems(value: unknown): unknown[] | null {
  if (types.isProxy(value) || !Array.isArray(value)) return null;
  const length = field(value, "length");
  if (typeof length !== "number" || !Number.isSafeInteger(length) || length < 0) return null;
  const descriptors = Object.getOwnPropertyDescriptors(value);
  if (Reflect.ownKeys(descriptors).length !== length + 1) return null;
  const result: unknown[] = [];
  for (let i = 0; i < length; i++) {
    const d = descriptors[String(i)];
    if (!d || !("value" in d)) return null;
    result.push(d.value);
  }
  return result;
}

export function getTimeConsortState(
  role: RoleComponent | undefined,
): TimeConsortReadState | undefined {
  if (field(role, "role") !== TIME_CONSORT_ROLE || field(role, "camp") !== Camp.Wolf)
    return undefined;
  const state = field(field(role, "privateState"), "timeConsort");
  if (!exact(state, ["policy", "reflectionScope", "history", "triggeredDay"])) return undefined;
  const scope = field(state, "reflectionScope"),
    trigger = field(state, "triggeredDay");
  if (
    field(state, "policy") !== TIME_CONSORT_POLICY ||
    (scope !== "whole_night" && scope !== "first_effect") ||
    (trigger !== null && !integer(trigger))
  )
    return undefined;
  const history = arrayItems(field(state, "history"));
  if (!history) return undefined;
  let previous = 0,
    previousTarget: number | null = null,
    triggerFound = trigger === null;
  for (const row of history) {
    if (!exact(row, ["day", "targetId"])) return undefined;
    const day = field(row, "day"),
      target = field(row, "targetId");
    if (
      !integer(day) ||
      day <= previous ||
      (target !== null && !integer(target)) ||
      (typeof trigger === "number" && day > trigger)
    )
      return undefined;
    if (target !== null && day === previous + 1 && target === previousTarget) return undefined;
    if (day === trigger) {
      if (target === null) return undefined;
      triggerFound = true;
    }
    previous = day;
    previousTarget = target as number | null;
  }
  if (!triggerFound) return undefined;
  return state as TimeConsortReadState;
}
export function createTimeConsortState(
  reflectionScope: ReflectionScope = "whole_night",
): TimeConsortState {
  return { policy: TIME_CONSORT_POLICY, reflectionScope, history: [], triggeredDay: null };
}
/** Public-to-owner projection delays successful-trigger knowledge until the next night. */
export function projectTimeConsortState(role: RoleComponent | undefined, day: number) {
  const state = getTimeConsortState(role);
  if (!state || !integer(day)) return undefined;
  const history: TimeConsortChoice[] = [];
  for (const row of arrayItems(field(state, "history"))!) {
    const when = field(row, "day") as number;
    if (when > day) continue;
    history.push({ day: when, targetId: field(row, "targetId") as number | null });
  }
  const trigger = field(state, "triggeredDay") as number | null;
  return {
    policy: TIME_CONSORT_POLICY,
    reflectionScope: state.reflectionScope,
    history,
    exhausted: trigger !== null && trigger < day,
  };
}
/** Pure rule decision. Real effect ownership/version validation belongs to the night receipt. */
export function timeConsortReflectionTarget(
  role: RoleComponent | undefined,
  day: number,
  sourceCamp: Camp,
  sourceId: number,
  requestedId: number,
  kind: string,
): number {
  if (!integer(day) || !integer(sourceId) || !integer(requestedId))
    throw new Error("time_consort_invalid_target");
  const state = getTimeConsortState(role);
  if (!state) throw new Error("time_consort_invalid_state");
  if (sourceCamp !== Camp.Good || !["check", "guard", "poison"].includes(kind)) return requestedId;
  const choice = arrayItems(field(state, "history"))!.find((h) => field(h, "day") === day);
  if (field(choice, "targetId") !== requestedId) return requestedId;
  if (
    state.triggeredDay !== null &&
    (state.triggeredDay !== day || state.reflectionScope === "first_effect")
  )
    return requestedId;
  return sourceId;
}

/**
 * 负责定义玩家观察的完整纯数据结构及原脱离冻结程序。输入为已投影事实、自己的知识 DTO 和请求；
 * 输出保留所有原可选／nullable 字段，先 structuredClone，再按原 Object.values 递归 freeze。
 * 这里不含 World、角色原体或资源写句柄，不安装状态、解析新 schema 或授予行动权限。
 * 捕获方决定知识和候选；该数据契约不把未知阵营或当前许可猜测成已知事实。
 */
import type {
  PlayerHiddenWolfState,
  PlayerGravekeeperState,
  PlayerMechanicalState,
  PlayerAwakenedState,
  PlayerHybridState,
  PlayerBlackMarketState,
  PlayerMerchantState,
} from "@ai-werewolf-arena/game-contract/player-state-views";
import type { ActionRequest, Camp, Role } from "@ai-werewolf-arena/game-contract";
import type {
  PlayerGuardState,
  PlayerHunterState,
  PlayerWolfKingState,
  PlayerWhiteWolfKingState,
  PlayerKnightState,
  PlayerDreamerState,
  PlayerWolfBeautyState,
  PlayerBearState,
  PlayerIdiotState,
  PlayerSeerState,
  PlayerWitchState,
  PlayerRoleInspectionState,
} from "@ai-werewolf-arena/game-contract/player-state-views";
import type { PlayerNightAbility, OwnNightAction } from "@ai-werewolf-arena/game-contract/night-ability-views";
import type { PlayerDeathGun } from "@ai-werewolf-arena/game-contract/player-state-views";

/** 玩家决策端口只携带已投影事实和自己的知识，不提供 World。 */
export interface PlayerObservation {
  request: ActionRequest;
  identity: { role?: Role; camp?: Camp; name?: string };
  knownAliveIds: number[];
  teammateIds: number[];
  /** 自己在捕获时点的狼队行动资格；不附权限原因、对手状态或请求 lease，提交时仍重验。 */
  currentWolfActions: { canChat: boolean; canVoteForKill: boolean };
  abilities: PlayerNightAbility[];
  deathAbilities: PlayerDeathGun[];
  ownNightActions: OwnNightAction[];
  ownState: {
    fragrantPhantom?: import("@ai-werewolf-arena/game-contract/facts/fragrant-pair-seer").FragrantPlayerState;
    nightNoble?: import("@ai-werewolf-arena/game-contract/facts/noble-secret-body").NoblePlayerState;
    secretBody?: import("@ai-werewolf-arena/game-contract/facts/noble-secret-body").SecretBodyPlayerState;
    eclipse?: import("../mechanisms/roles/radiant_eclipse/state").EclipseState;
    alchemist?: import("@ai-werewolf-arena/game-contract/facts/mist-raven").PlayerAlchemistState;
    ravenClaw?: import("@ai-werewolf-arena/game-contract/facts/mist-raven").PlayerRavenState;
    scholarMentor?: import("@ai-werewolf-arena/game-contract").ModifierState;
    timeConsort?: NonNullable<
      ReturnType<
        typeof import("../mechanisms/roles/time_wolf_consort/state").projectTimeConsortState
      >
    >;
    wolfSorcerer?: import("@ai-werewolf-arena/game-contract").WolfSorcererState;
    trickster?: import("@ai-werewolf-arena/game-contract").TricksterState;
    orderPrince?: import("../mechanisms/roles/order_prince/state").OrderPrinceState;
    magician?: import("@ai-werewolf-arena/game-contract").MagicianState;
    redMoon?: import("@ai-werewolf-arena/game-contract").RedMoonState;
    nightmare?: import("@ai-werewolf-arena/game-contract").NightmareShadowState;
    evilKnight?: import("@ai-werewolf-arena/game-contract").EvilKnightState;
    demonHunter?: import("@ai-werewolf-arena/game-contract/facts/demon-hunter").DemonHunterState;
    ghostBride?: import("@ai-werewolf-arena/game-contract/facts/ghost-bride").GhostBrideState;
    wedding?: import("../mechanisms/roles/ghost_bride/authority").WeddingActorView;
    lonelyGirl?: import("@ai-werewolf-arena/game-contract").LonelyGirlState;
    wildChild?: import("@ai-werewolf-arena/game-contract").WildChildState;
    thief?: import("@ai-werewolf-arena/game-contract").ThiefState & {
      required?: boolean;
      cards?: Array<{ slot: 0 | 1; role: Role }>;
    };
    shapeshifter?: import("@ai-werewolf-arena/game-contract").ShapeshifterState & {
      mustChoose?: boolean;
      allowedSlots?: Array<0 | 1>;
      cards?: Array<{ slot: 0 | 1; role: Role }>;
    };
    wallNote?: import("../../core/domain/components/wall_note").WallNoteComponent & {
      effectiveRemaining: 0 | 1;
    };
    blackMarket?: PlayerBlackMarketState;
    awakened?: PlayerAwakenedState;
    hybrid?: PlayerHybridState;
    debater?: {
      policy: import("../../core/domain/board").DebaterPolicy;
      remaining: 0 | 1;
      choice: { day: number; targetId: number } | null;
    };
    debatePenalty?: { day: number };
    cupid?: import("@ai-werewolf-arena/game-contract/player-state-views").PlayerCupidState;
    lover?: { partnerId: number; mayNotVotePartner: boolean };
    merchant?: PlayerMerchantState;
    mechanical?: PlayerMechanicalState;
    witch?: PlayerWitchState;
    guard?: PlayerGuardState;
    hunter?: PlayerHunterState;
    wolfKing?: PlayerWolfKingState;
    whiteWolfKing?: PlayerWhiteWolfKingState;
    knight?: PlayerKnightState;
    gravekeeper?: PlayerGravekeeperState;
    dreamer?: PlayerDreamerState;
    wolfBeauty?: PlayerWolfBeautyState;
    bear?: PlayerBearState;
    foxCub?: { remaining: 0 | 1; lastChoice: { day: number; targetId: number | null } | null };
    pufferfish?: { remaining: 0 | 1; lastDecision: { day: number; activate: boolean } | null };
    whiteCat?: { revealed: boolean };
    hiddenWolf?: PlayerHiddenWolfState;
    gargoyle?: { hasInheritedKnife: boolean; canVoteForKill: boolean };
    roleInspection?: PlayerRoleInspectionState;
    idiot?: PlayerIdiotState;
    seer?: PlayerSeerState;
  };
}

export interface ObservedPlayerStrategy {
  decide(
    observation: PlayerObservation,
  ): Promise<import("@ai-werewolf-arena/game-contract").ToolCall | null>;
}

/** 先复制再递归冻结，避免策略修改引擎或污染后续观察；保持原接受集合和失败顺序。 */
export function freezeObservation(observation: PlayerObservation): PlayerObservation {
  const result = structuredClone(observation);
  const freeze = (value: unknown) => {
    if (value && typeof value === "object") {
      Object.values(value).forEach(freeze);
      Object.freeze(value);
    }
  };
  freeze(result);
  return result;
}
